.gradient-text {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-width: 100%;
  isolation: isolate;
}

.gradient-text--border {
  padding: 0.35em 0.75em;
  border-radius: 999px;
}

.gradient-text--border::before {
  content: '';
  position: absolute;
  inset: 0;
  padding: var(--gt-border);
  border-radius: inherit;
  background-image: var(--gt-gradient);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box exclude,
    linear-gradient(#000 0 0);
  pointer-events: none;
}

.gradient-text__inner {
  position: relative;
  display: inline-block;
}

.gradient-text__content {
  display: inline-block;
  background-image: var(--gt-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.gradient-text__glow {
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image: var(--gt-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: blur(0.3em) saturate(1.4);
  opacity: var(--gt-glow);
  pointer-events: none;
  user-select: none;
}

import { Show, createEffect, createMemo, onSettled } from 'solid-js';
import type { JSX } from '@solidjs/web';

import './GradientText.css';

type Variant = 'linear' | 'flow' | 'conic';

export interface GradientTextProps {
  children?: JSX.Element;
  colors?: string[];
  animationSpeed?: number;
  variant?: Variant;
  angle?: number;
  direction?: 'horizontal' | 'vertical' | 'diagonal';
  scale?: number;
  yoyo?: boolean;
  glow?: number;
  showBorder?: boolean;
  borderWidth?: number;
  pauseOnHover?: boolean;
  followPointer?: boolean;
  className?: string;
  style?: JSX.CSSProperties;
}

interface Settings {
  colors: string[];
  speed: number;
  variant: Variant;
  angle: number;
  scale: number;
  yoyo: boolean;
  pauseOnHover: boolean;
  followPointer: boolean;
}

const DEFAULT_COLORS = ['#0aa0ef', '#6ec9f7', '#b4d4ec'];
const VARIANTS: Variant[] = ['linear', 'flow', 'conic'];
const ANGLES: Record<string, number> = { horizontal: 90, vertical: 180, diagonal: 135 };
const TAU = Math.PI * 2;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

export default function GradientText(props: GradientTextProps) {
  let rootEl: HTMLSpanElement | undefined;
  let current!: Settings;
  let wake: (() => void) | null = null;

  const palette = createMemo(() => {
    const colors = props.colors ?? DEFAULT_COLORS;
    return colors.length > 1 ? colors : [colors[0] ?? '#ffffff', colors[0] ?? '#ffffff'];
  });

  const resolvedAngle = createMemo(() => {
    const angle = props.angle ?? 90;
    return props.direction ? (ANGLES[props.direction] ?? angle) : angle;
  });

  const settings = createMemo<Settings>(() => {
    const variant = props.variant ?? 'linear';
    return {
      colors: palette(),
      speed: Math.max(0.2, props.animationSpeed ?? 8),
      variant: VARIANTS.includes(variant) ? variant : 'linear',
      angle: resolvedAngle(),
      scale: clamp(props.scale ?? 3, 1, 6),
      yoyo: props.yoyo ?? true,
      pauseOnHover: props.pauseOnHover ?? false,
      followPointer: props.followPointer ?? false
    };
  });

  createEffect(settings, value => {
    current = value;
    wake?.();
  });

  onSettled(() => {
    current = settings();
    const root = rootEl;
    if (!root) return;

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const state = { time: 0, inside: false, visible: true, x: 0.5, y: 0.5, px: 0.5, py: 0.5, vx: 0, vy: 0, pull: 0 };
    let raf = 0;
    let last = 0;
    let alive = true;

    const paint = () => {
      const s = current;
      const list = s.colors;
      const cycle = state.time / s.speed;
      let image;
      if (s.variant === 'flow') {
        const blobs = list.map((color, i) => {
          const spin = cycle * TAU;
          const rate = 0.55 + ((i * 0.618) % 1) * 0.5;
          let x = 50 + 44 * Math.sin(spin * rate + i * 2.1);
          let y = 50 + 40 * Math.sin(spin * (rate * 0.83 + 0.21) + i * 1.3);
          if (i === 0) {
            x += (state.px * 100 - x) * state.pull;
            y += (state.py * 100 - y) * state.pull;
          }
          return `radial-gradient(ellipse ${(22 + 12 * s.scale).toFixed(1)}% ${(60 + 30 * s.scale).toFixed(1)}% at ${x.toFixed(2)}% ${y.toFixed(2)}%, ${color} 0%, transparent 100%)`;
        });
        image = `${blobs.join(', ')}, linear-gradient(${s.angle}deg, ${list.join(', ')})`;
      } else if (s.variant === 'conic') {
        const sway = s.yoyo ? Math.sin(cycle * Math.PI) * 50 : cycle * 360;
        const cx = 50 + (state.px * 100 - 50) * state.pull;
        const cy = 260 + (state.py * 100 - 260) * state.pull;
        image = `repeating-conic-gradient(from ${(sway - 30).toFixed(2)}deg at ${cx.toFixed(2)}% ${cy.toFixed(2)}%, ${[...list, list[0]].map((color, i) => `${color} ${((i / list.length) * 60 * (3 / s.scale)).toFixed(2)}deg`).join(', ')})`;
      } else {
        const loop = [...list, list[0]];
        const period = 100 * s.scale;
        let offset;
        if (s.yoyo) {
          const swing = cycle % 2;
          const t = swing < 1 ? swing : 2 - swing;
          offset = (0.5 - Math.cos(Math.PI * t) / 2) * (period - 100);
        } else {
          offset = (cycle % 1) * period;
        }
        offset += (state.px - 0.5) * period * 0.5 * state.pull;
        const stops = loop.map((color, i) => `${color} ${((i / (loop.length - 1)) * period - offset).toFixed(2)}%`);
        image = `repeating-linear-gradient(${s.angle}deg, ${stops.join(', ')})`;
      }
      root.style.setProperty('--gt-gradient', image);
    };

    const tick = (now: number) => {
      raf = 0;
      if (!alive) return;
      const s = current;
      const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
      last = now;
      const paused = reduce || (s.pauseOnHover && state.inside);
      if (!paused) state.time += dt;
      const target = s.followPointer && state.inside ? 1 : 0;
      state.pull += (target - state.pull) * (1 - Math.exp(-dt * 6));
      const stiffness = 160;
      state.vx += ((state.x - state.px) * stiffness - state.vx * 2 * Math.sqrt(stiffness)) * dt;
      state.vy += ((state.y - state.py) * stiffness - state.vy * 2 * Math.sqrt(stiffness)) * dt;
      state.px += state.vx * dt;
      state.py += state.vy * dt;
      paint();
      const settling = Math.abs(state.pull - target) > 0.001 || Math.abs(state.vx) + Math.abs(state.vy) > 0.001;
      if (!state.visible || (paused && !settling)) return;
      raf = requestAnimationFrame(tick);
    };

    const start = () => {
      if (raf || !alive) return;
      last = performance.now();
      raf = requestAnimationFrame(tick);
    };
    wake = () => {
      paint();
      start();
    };

    const locate = (event: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      state.x = clamp((event.clientX - rect.left) / rect.width, 0, 1);
      state.y = clamp((event.clientY - rect.top) / rect.height, 0, 1);
    };
    const onEnter = (event: PointerEvent) => {
      locate(event);
      if (!state.inside) {
        state.px = state.x;
        state.py = state.y;
      }
      state.inside = true;
      start();
    };
    const onMove = (event: PointerEvent) => {
      locate(event);
      start();
    };
    const onLeave = () => {
      state.inside = false;
      start();
    };

    const observer = new IntersectionObserver(entries => {
      state.visible = entries.some(entry => entry.isIntersecting);
      if (state.visible) start();
    });
    observer.observe(root);
    root.addEventListener('pointerenter', onEnter);
    root.addEventListener('pointermove', onMove);
    root.addEventListener('pointerleave', onLeave);
    paint();
    start();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      observer.disconnect();
      root.removeEventListener('pointerenter', onEnter);
      root.removeEventListener('pointermove', onMove);
      root.removeEventListener('pointerleave', onLeave);
      wake = null;
    };
  });

  return (
    <span
      ref={el => (rootEl = el)}
      class={['gradient-text', { 'gradient-text--border': props.showBorder ?? false }, props.className]}
      style={{
        '--gt-gradient': `linear-gradient(${resolvedAngle()}deg, ${[...palette(), palette()[0]].join(', ')})`,
        '--gt-border': `${props.borderWidth ?? 1.5}px`,
        '--gt-glow': String(clamp(props.glow ?? 0, 0, 1)),
        ...props.style
      }}
    >
      <span class="gradient-text__inner">
        <span class="gradient-text__content">{props.children}</span>
        <Show when={(props.glow ?? 0) > 0}>
          <span class="gradient-text__glow" aria-hidden="true">
            {props.children}
          </span>
        </Show>
      </span>
    </span>
  );
}
